"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[30095],{29978:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ShopPerkConfig","desc":"The 88 shop perks (Perk Rework part 2 + 16 super rares): 40 Consumable (the run uses one copy\\nwhen it starts; the effect lasts the whole run) and 48 Expiring (a real-time\\nclock that starts on the first equip and never stops). Players buy them with\\ncoins and equip them in the Lobby only. `Family` = stat family label for the\\ncatalog and GUI; no rule reads it (same-family perks stack). `ExclusiveGroup`\\nperks never share a pool\'s loadout (XP Booster I/II, Coin Booster I/II, and each super rare with its twin). `Buffs` are read\\nby Perk Rework part 3. `Hidden` perks need part 5\\ncode: not buyable, not equippable (a grant still lands in the inventory).\\n`BoxOnly` perks (the 16 super rares) come only from a perk box: the shop\\nhides them and a buy is rejected; they equip like any expiring perk.\\nPer project convention, tune shop perks here, not in code.","source":{"line":17,"path":"src/ReplicatedStorage/SharedModules/Configs/ShopPerkConfig.luau"}}')}}]);